from __future__ import annotations
import base64, hashlib, json, shutil, tempfile, zipfile, zlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
ARCHIVE=ROOT/'apps'/'his_risen_controller_ltx25_audited_update_2026-10-10 (2).zip'
MANIFEST=Path(str(ARCHIVE)+'.sha256')
BASE='6084b3b9225c1776ded7a25d43660d6628107bf8993430718ed5219605784090'
TARGET='/tmp/his-risen-production-readiness'
PAYLOAD_ZLIB_B64=''
def replace_once(files,path,old,new,label):
    if path not in files: raise SystemExit(f'missing package file: {path}')
    value=files[path].decode('utf-8')
    if value.count(old)!=1: raise SystemExit(f'{label}: expected one anchor, got {value.count(old)}')
    files[path]=value.replace(old,new,1).encode('utf-8')
def main():
    digest=hashlib.sha256(ARCHIVE.read_bytes()).hexdigest()
    with zipfile.ZipFile(ARCHIVE) as z:
        infos=z.infolist(); files={i.filename:z.read(i.filename) for i in infos if not i.is_dir()}
    if digest==BASE:
        replace_once(files,'controller/service.py',
          'def __init__(self,root:Path,profiles:ProfileRegistry,workflows:WorkflowRegistry,store:SQLiteStore,adapter:GenerationAdapter,export_manager:ApprovedOutputExportManager|None=None,auto_export_approved:bool=False,capability_registry:LTX25CapabilityRegistry|None=None):\n        self.root=root.resolve(); self.profiles=profiles;',
          'def __init__(self,root:Path,profiles:ProfileRegistry,workflows:WorkflowRegistry,store:SQLiteStore,adapter:GenerationAdapter,export_manager:ApprovedOutputExportManager|None=None,auto_export_approved:bool=False,capability_registry:LTX25CapabilityRegistry|None=None,asset_root:Path|None=None):\n        self.root=root.resolve(); self.asset_root=(asset_root or self.root).resolve(); self.profiles=profiles;', 'controller asset-root constructor')
        old='validate_specification(spec,self.root)'
        new='validate_specification(spec,self.asset_root)'
        count=files['controller/service.py'].decode().count(old)
        if count != 3: raise SystemExit(f'controller validation root expected 3 anchors, got {count}')
        files['controller/service.py']=files['controller/service.py'].decode().replace(old,new).encode()
        replace_once(files,'controller/service.py','validate_assets(snapshot["profiles"]["reference_assets"],self.root,"saved reference_assets",errors)','validate_assets(snapshot["profiles"]["reference_assets"],self.asset_root,"saved reference_assets",errors)','regeneration asset root')
        replace_once(files,'comfyui/adapter.py',
          'def __init__(self, root: Path, base_url: str, timeout: float = 30.0, job_timeout: float = 3600.0, headers: dict[str, str] | None = None):\n        self.root = root.resolve()',
          'def __init__(self, root: Path, base_url: str, timeout: float = 30.0, job_timeout: float = 3600.0, headers: dict[str, str] | None = None, asset_root: Path | None = None):\n        self.root = root.resolve()\n        self.asset_root = (asset_root or self.root).resolve()', 'adapter asset-root constructor')
        replace_once(files,'comfyui/adapter.py',
          '            local_path = (self.root / asset["path"]).resolve()\n            result = self.http.upload_file(local_path,',
          '            relative_path = Path(asset["path"])\n            if relative_path.is_absolute() or ".." in relative_path.parts:\n                raise ComfyUIProtocolError(f"reference asset path must remain inside the configured asset root: {asset_id}")\n            local_path = (self.asset_root / relative_path).resolve()\n            if not local_path.is_relative_to(self.asset_root) or not local_path.is_file():\n                raise ComfyUIProtocolError(f"reference asset is missing or outside the configured asset root: {asset_id}")\n            result = self.http.upload_file(local_path,', 'adapter safe persistent asset lookup')
        replace_once(files,'config/bootstrap.py','        project_root,\n    )\n    workflows = WorkflowRegistry','        data_root,\n    )\n    workflows = WorkflowRegistry','profile registry asset root')
        replace_once(files,'config/bootstrap.py','            headers=headers,\n        )\n\n    return Controller(','            headers=headers,\n            asset_root=data_root,\n        )\n\n    return Controller(','adapter asset root config')
        replace_once(files,'config/bootstrap.py','        auto_export_approved=bool(runtime.get("auto_export_approved", False)),\n    )','        auto_export_approved=bool(runtime.get("auto_export_approved", False)),\n        asset_root=data_root,\n    )','controller asset root config')
        payload=json.loads(zlib.decompress(base64.b64decode(PAYLOAD_ZLIB_B64)).decode())
        for path,encoded in payload.items(): files[path]=base64.b64decode(encoded)
        replace_once(files,'tests/test_integration_layers.py',
          '            adapter = RealComfyUIAdapter(work, fake.base_url, timeout=2, job_timeout=10)\n            asset = work / "refs" / "input.png"\n            asset.write_bytes(b"PNG-TEST")',
          '            asset_root = Path(tempfile.mkdtemp(prefix="his-risen-persistent-assets-"))\n            asset = asset_root / "assets" / "input.png"\n            asset.parent.mkdir(parents=True)\n            asset.write_bytes(b"PNG-TEST")\n            adapter = RealComfyUIAdapter(work, fake.base_url, timeout=2, job_timeout=10, asset_root=asset_root)', 'real adapter persistent asset test')
        replace_once(files,'tests/test_integration_layers.py','"path":"refs/input.png"','"path":"assets/input.png"','real adapter persistent reference path')
        doc=files['docs/REAL_COMFYUI.md'].decode()
        anchor='## What is required outside the controller\n'
        addition='## Reference assets and persistent storage\n\nWhen HRF_DATA_DIR points to an attached durable volume, reference-asset paths are resolved relative to that root (for example, assets/characters/moses-front.png). Copy the registered files into the mounted volume before submitting a shot. Profile definitions, workflow graphs and node mappings remain application files in the package; referenced media files live under the data root. The ComfyUI adapter rejects absolute paths, parent-directory traversal and resolved paths outside the configured data root.\n\nThe package includes python -m storage.backup backup, python -m storage.backup verify --backup PATH, and python -m storage.backup restore --backup PATH --confirm-stopped. Stop the Director Console before restore. Restore verifies checksum and SQLite integrity, keeps a pre-restore copy, then atomically replaces the database. Default backups are stored under HRF_DATA_DIR/backups. This is same-volume recovery, not offsite disaster protection; production should also copy verified backups to separate object storage and test restores periodically.\n\n'
        if doc.count(anchor)!=1: raise SystemExit('REAL_COMFYUI documentation anchor mismatch')
        files['docs/REAL_COMFYUI.md']=doc.replace(anchor,addition+anchor,1).encode()
    else:
        if 'storage/backup.py' not in files or b'self.asset_root' not in files.get('comfyui/adapter.py',b''):
            raise SystemExit(f'unexpected base archive digest: {digest}')
        line=MANIFEST.read_text().strip()
        if line!=f'{digest}  {ARCHIVE.name}': raise SystemExit('patched package manifest mismatch')
        print('STORAGE_PATCH_ALREADY_PRESENT'); return
    tmp=ARCHIVE.with_suffix('.tmp.zip')
    try:
        with zipfile.ZipFile(tmp,'w',compression=zipfile.ZIP_DEFLATED) as z:
            seen=set()
            fixed_time=(2026,1,1,0,0,0)
            for info in infos:
                info.date_time=fixed_time
                if info.is_dir(): z.writestr(info,b'')
                else: z.writestr(info,files[info.filename]); seen.add(info.filename)
            for path,data in files.items():
                if path not in seen:
                    info=zipfile.ZipInfo(path,date_time=fixed_time)
                    info.compress_type=zipfile.ZIP_DEFLATED
                    info.create_system=3
                    info.external_attr=(0o100644 << 16)
                    z.writestr(info,data)
        with zipfile.ZipFile(tmp) as z:
            bad=z.testzip()
            if bad: raise SystemExit(f'ZIP integrity failed: {bad}')
        shutil.move(tmp,ARCHIVE)
    finally: tmp.unlink(missing_ok=True)
    digest=hashlib.sha256(ARCHIVE.read_bytes()).hexdigest()
    MANIFEST.write_text(f'{digest}  {ARCHIVE.name}\n')
    shutil.rmtree(TARGET,ignore_errors=True); Path(TARGET).mkdir(parents=True,exist_ok=True)
    with zipfile.ZipFile(ARCHIVE) as z: z.extractall(TARGET)
    print('STORAGE_PATCH_APPLIED')
    print('PACKAGE_SHA256',digest)
    print('PACKAGE_BYTES',ARCHIVE.stat().st_size)
    print('TEST_ROOT',TARGET)
if __name__=='__main__': main()
